'use client';

import React from 'react';

/** State of the thinking block. */
export type ThinkingBlockState = 'thinking' | 'done' | 'error';

/** Props for the {@link ThinkingBlock} component. */
export interface ThinkingBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current thinking state. */
  state?: ThinkingBlockState;
  /** Label text displayed in the header. */
  label?: string;
  /** Metadata string (e.g. duration) displayed to the right. */
  meta?: string;
  /** Whether the block is expanded. When undefined, defaults to `true` during thinking. */
  expanded?: boolean;
  /** Default expanded state (uncontrolled). */
  defaultExpanded?: boolean;
  /** Called when the expanded state changes. */
  onExpandedChange?: (expanded: boolean) => void;
  /** Additional CSS class names. */
  className?: string;
  /** Thinking content displayed when expanded. */
  children?: React.ReactNode;
}

/**
 * AI extended thinking block with pulse animation and expand/collapse.
 * Auto-expands while `state` is `"thinking"` and collapses when `"done"`.
 */
export const ThinkingBlock = React.forwardRef<HTMLDivElement, ThinkingBlockProps>(
  (
    {
      state = 'thinking',
      label = 'Thinking...',
      meta,
      expanded: controlledExpanded,
      defaultExpanded,
      onExpandedChange,
      className,
      children,
      ...rest
    },
    ref,
  ) => {
    const [internal, setInternal] = React.useState(defaultExpanded ?? state === 'thinking');
    const isExpanded = controlledExpanded ?? internal;

    // Auto-expand/collapse based on state changes
    React.useEffect(() => {
      if (controlledExpanded !== undefined) return;
      if (state === 'thinking') setInternal(true);
      else if (state === 'done') setInternal(false);
    }, [state, controlledExpanded]);

    const toggle = React.useCallback(() => {
      const next = !isExpanded;
      if (controlledExpanded === undefined) setInternal(next);
      onExpandedChange?.(next);
    }, [isExpanded, controlledExpanded, onExpandedChange]);

    return (
      <div
        ref={ref}
        className={`sk-thinking-block${className ? ` ${className}` : ''}`}
        data-state={state}
        data-expanded={isExpanded ? 'true' : 'false'}
        {...rest}
      >
        <button className="sk-thinking-block__header" onClick={toggle} aria-expanded={isExpanded}>
          <span className="sk-thinking-block__dot" />
          <span className="sk-thinking-block__label">{label}</span>
          {meta && <span className="sk-thinking-block__meta">{meta}</span>}
          <i className="sk-thinking-block__chevron">{'\u25B8'}</i>
        </button>
        {isExpanded && children && (
          <div className="sk-thinking-block__content">{children}</div>
        )}
      </div>
    );
  },
);

ThinkingBlock.displayName = 'ThinkingBlock';

/**
 * skeehn — ThinkingBlock Component
 *
 * @component sk-thinking-block
 * @states    [data-state="thinking"] | [data-state="done"] | [data-state="error"] | [data-expanded]
 * @slots     __header | __dot | __label | __meta | __chevron | __content | __token-count
 * @features  Progressive disclosure, nested thinking, live token count, scanline overlay
 * @a11y      Button trigger, aria-expanded, focus-visible, reduced motion
 * @print     Expanded content visible, animations disabled
 */

.sk-thinking-block {
  border: 1px solid hsl(var(--sk-border-color));
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  position: relative;
  overflow: hidden;
  transition: border-color var(--sk-transition-slow);
}

.sk-thinking-block[data-state="thinking"] {
  border-color: hsl(var(--sk-muted-foreground) / 0.35);
}
.sk-thinking-block[data-state="error"] {
  border-color: hsl(var(--sk-destructive) / 0.5);
}

/* ── Header ── */
.sk-thinking-block__header {
  display: flex;
  align-items: center;
  gap: var(--sk-space-2);
  padding: var(--sk-space-2) var(--sk-space-3);
  cursor: pointer;
  user-select: none;
  background: hsl(var(--sk-surface));
  border: none;
  width: 100%;
  text-align: left;
  color: hsl(var(--sk-muted-foreground));
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  transition: background var(--sk-transition), color var(--sk-transition);
}
.sk-thinking-block__header:hover {
  background: hsl(var(--sk-accent));
  color: hsl(var(--sk-foreground));
}
.sk-thinking-block__header:focus-visible {
  outline: 2px solid hsl(var(--sk-ring));
  outline-offset: -2px;
}

/* ── Animated dot ── */
.sk-thinking-block__dot {
  width: 6px;
  height: 6px;
  flex-shrink: 0;
  background: hsl(var(--sk-muted-foreground));
}
.sk-thinking-block[data-state="thinking"] .sk-thinking-block__dot {
  background: hsl(var(--sk-foreground));
  animation: sk-thinking-pulse 1.2s steps(2) infinite;
}
.sk-thinking-block[data-state="done"] .sk-thinking-block__dot {
  background: hsl(var(--sk-success));
}
.sk-thinking-block[data-state="error"] .sk-thinking-block__dot {
  background: hsl(var(--sk-destructive));
}

@keyframes sk-thinking-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.15; }
}

.sk-thinking-block__label {
  flex: 1;
  letter-spacing: 0.04em;
}
.sk-thinking-block__meta {
  font-size: 9px;
  opacity: 0.45;
}
.sk-thinking-block__chevron {
  font-style: normal;
  transition: transform var(--sk-transition);
  opacity: 0.5;
}
.sk-thinking-block[data-expanded="true"] .sk-thinking-block__chevron {
  transform: rotate(90deg);
}

/* ── Content ── */
.sk-thinking-block__content {
  display: none;
  padding: var(--sk-space-3) var(--sk-space-4);
  color: hsl(var(--sk-muted-foreground));
  line-height: 1.65;
  border-top: 1px solid hsl(var(--sk-border-color));
  max-height: 280px;
  overflow-y: auto;
  background: hsl(var(--sk-surface));
  position: relative;
}
.sk-thinking-block[data-expanded="true"] .sk-thinking-block__content {
  display: block;
}

/* Dim live reasoning while actively thinking; settle to full muted on done. */
.sk-thinking-block[data-state="thinking"] .sk-thinking-block__content {
  opacity: 0.72;
  transition: opacity var(--sk-transition-slow);
}

/* Scanline texture overlay */
.sk-thinking-block__content::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-scanlines);
  background-size: 100% 4px;
  opacity: 0.04;
  pointer-events: none;
}

/* Blinking cursor while actively thinking */
.sk-thinking-block[data-state="thinking"] .sk-thinking-block__content::after {
  content: "▊";
  animation: sk-cursor-blink 0.8s steps(2) infinite;
}
@keyframes sk-cursor-blink {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0; }
}

/* ── Progressive disclosure — nested thinking ── */
.sk-thinking-block .sk-thinking-block {
  margin: var(--sk-space-2) 0;
  margin-left: var(--sk-space-3);
  border-left: 2px solid hsl(var(--sk-border-color));
  border-top: none;
  border-right: none;
  border-bottom: none;
}

.sk-thinking-block .sk-thinking-block .sk-thinking-block__header {
  font-size: 0.6rem;
  padding: var(--sk-space-1) var(--sk-space-2);
}

/* ── Live token count ── */
.sk-thinking-block__token-count {
  font-family: var(--sk-font-mono);
  font-size: 0.55rem;
  color: hsl(var(--sk-muted-foreground) / 0.4);
  letter-spacing: 0.05em;
  margin-left: auto;
  padding-left: var(--sk-space-2);
  font-variant-numeric: tabular-nums;
}

.sk-thinking-block[data-state="thinking"] .sk-thinking-block__token-count {
  animation: sk-thinking-pulse 1.2s steps(2) infinite;
}

/* ── Dither fill while thinking ── */
@keyframes sk-thinking-dither-fill {
  0%   { background-image: var(--sk-dither-b2); opacity: 0.02; }
  50%  { background-image: var(--sk-dither-b6); opacity: 0.05; }
  100% { background-image: var(--sk-dither-b2); opacity: 0.02; }
}

.sk-thinking-block[data-state="thinking"] .sk-thinking-block__content::after {
  content: "";
  position: absolute;
  inset: 0;
  background-repeat: repeat;
  animation: sk-thinking-dither-fill 3s steps(4) infinite;
  pointer-events: none;
}

@media print {
  .sk-thinking-block { border: 1px solid hsl(var(--sk-foreground)); }
  .sk-thinking-block__content { display: block; max-height: none; }
  .sk-thinking-block__content::before,
  .sk-thinking-block__content::after { display: none; }
  .sk-thinking-block__dot { animation: none; }
  .sk-thinking-block__chevron { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-thinking-block__dot                { animation: none; }
  .sk-thinking-block__content::after     { animation: none; content: ""; }
  .sk-thinking-block__chevron            { transition: none; }
  .sk-thinking-block__header             { transition: none; }
  .sk-thinking-block__token-count        { animation: none; }
}
